#include <cstdio>
#include <cstring>
struct Str {
    char buf[128];
    Str() { buf[0] = 0; }
    Str(const char* s) { std::strcpy(buf, s); }
    Str& operator+=(const Str& o) { std::strcat(buf, o.buf); return *this; }
};
static Str operator+(const char* l, const Str& r) { Str s(l); s += r; return s; }
